mapper.select:
SELECT id, user_id, medicine_name, dosage, frequency, start_date, end_date, notes FROM t_medication  AND id = #{id}
 AND user_id = #{userId}
 AND medicine_name LIKE CONCAT('%', #{medicineName}, '%')
 AND dosage LIKE CONCAT('%', #{dosage}, '%')
 AND frequency LIKE CONCAT('%', #{frequency}, '%')
 AND start_date = #{startDate}
 AND end_date = #{endDate} ORDER BY id DESC
